<span class="line">    <span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&quot;시크릿 데이터:&quot;</span><span class="token punctuation">,</span> secret_response<span class="token punctuation">[</span><span class="token string">&#39;data&#39;</span><span class="token punctuation">]</span><span class="token punctuation">[</span><span class="token string">&#39;data&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
